f = "39c2764e-f378-4265-ba09-eaeed14656e2.jsonl"
kinds = collections.Counter()
for line in open(f, encoding="utf-8"):
    d = json.loads(line)
    t = d.get("type")
    if t in ("user","assistant"):
        c = d["message"]["content"]
        if isinstance(c, str):
            kinds[(t,"str",bool(d.get("isMeta")))] += 1
            print("USERSTR:", repr(c[:300]))
        else:
            for b in c:
                kinds[(t,b.get("type"),bool(d.get("isMeta")))] += 1
                if b.get("type")=="thinking":
                    print("THINKING len", len(b.get("thinking","")))
                if b.get("type")=="text" and t=="user":
                    print("USERTEXT meta=",d.get("isMeta"), repr(b["text"][:200]))
    elif t=="system":
        print("SYSTEM:", d.get("subtype"), repr(str(d.get("content"))[:200]))
print(kinds)
